import React from 'react';
import { Link } from 'react-router-dom';
import { decode } from '../../../lib/code-mnem'
import {HOSTURL} from "../../../index.js"


const Emotes = (props) => {
	const encoded = decode(props.emote.code)

	return (
		<div className="div_emoteCard">
			<Link to={"/emotes/" + props.emote._id } className="emoteCard" title={encoded}>
				<img src={HOSTURL + "/cached/emote/"+ props.emote._id +"/2x"} alt={encoded}/>
				<div>
					<span>{encoded}</span>
				</div>
			</Link>
		</div>
	);
};

export default Emotes;