import React, {useState} from 'react';
import useTitle from '../components/JS/Title'
import NavbarDashboard from "../components/UI/NavbarDashboard/NavbarDashboard"
import api from "../services/api"
import useAuth from "../hooks/useAuth"
import { Slide } from 'react-slideshow-image';
import 'react-slideshow-image/dist/styles.css'
import classnames from 'classnames';
import {HexColorPicker} from 'react-colorful'

const Emotes = (props) => {
	useTitle('BetterWASD | Цвет имени')

	const auth = useAuth();

	const [color, setColor] = useState(auth.user?.paint?.length < 5 ? Number(auth.user?.paint) : 0)
	const [hexColor, setHexColor] = useState(auth.user?.paint?.length < 5 ? '#ffffff' : auth.user?.paint)
	const [isPicker, setPicker] = useState(auth.user?.paint?.length > 5)

	const slideImages = [];
	for (var i = 0; i < 21; i++) {
		slideImages.push({
			url: 'https://raw.githubusercontent.com/ovgamesdev/BetterWASD.data/release/paints/'+i+'.webp',
			id: i
		})
	}
	const properties = {
		autoplay: false,
		defaultIndex: color,
	  onChange: (oldIndex, newIndex) => setColor(newIndex)
	}
	
	const onSave = async () => {
		const paint = getColor()
		await api.paint.setPaint({paint: paint})
		auth.setUser({...auth.user, paint: paint})
	}

	const getColor = () => {
		return isPicker ? hexColor : color
	}

	console.log(getColor() == auth.user.paint)
	console.log(getColor(), auth.user.paint)

	return (
		<section className="question-section paint" style={{paddingBottom: '160px'}}>
			<div className="items">
				<div className="item item_left">
					<NavbarDashboard defaultActiveKey="#/dashboard/paint" />
				</div>
				<div className="item block item_right" style={{marginTop: '0px'}}>
					<div className="item__title"> Цвет имени </div>
					<div className="item__descr"> Цвет доступен пользователям с BetterWASD. </div>
					<div className="item__border"></div>

					<div style={{display: 'flex', alignItems: 'center', paddingBottom: '15px'}}>
						<input type="checkbox" id="isPicker" checked={isPicker} onChange={(e) => setPicker(e.target.checked)} style={{'width': '20px', 'height': '20px'}}></input>
						<label htmlFor="isPicker" style={{paddingLeft: '5px'}}>Выбор цвета</label>
					</div>

					
					{
						isPicker
					?
						<HexColorPicker style={{width:'260px'}} color={hexColor} onChange={setHexColor} />
					:
						<div style={{width: '200px', right: '27%'}} className="slideshow-container">
							<Slide {...properties}>
								{slideImages.map((slideImage, index)=> (
									<div className="each-slide" key={index}>
										<div className="slideshow-img" style={{backgroundImage: `url(${slideImage.url})`, width: '200px', height: '120px'}}></div>
									</div>
								))}
							</Slide>
						</div>
					}

					<div className="flat-btn ovg" style={{display: 'flex', paddingTop: '5px'}}><button onClick={onSave} className={classnames('primary', 'medium', 'ovg', 'updateUser', getColor() == auth.user.paint ? 'disabled' : '')}> Сохранить </button></div>
					
				</div>
			</div>
		</section>
	);
};

export default Emotes;