import React, { useState } from 'react';
import {useNavigate, useSearchParams} from 'react-router-dom';
import 'react-slideshow-image/dist/styles.css';
import './modal.css';
import './button.css';
import './input.css';
import classnames from 'classnames';
import api from "../services/api"
import useAuth from "../hooks/useAuth"

const Home = () => {
	const auth = useAuth();
  const navigate = useNavigate();
	const [searchParams, setSearchParams] = useSearchParams();

	const [showAuth, setShowAuth] = useState(false)

  const [error, setError] = useState(null);
  const [isLoading, setIsLoading] = useState(false);


  const [token, setToken] = useState("undefined");

	const onSubmit = async () => {
		try {
			setIsLoading(true)
			const {data: loginData} = await api.auth.checkToken({token: token})

			auth.setToken(loginData.token)
			auth.setUser(loginData.user)
		} catch (e) {
			console.log(e.message.match('404'), e.message.match('401'))
			if (e.message.match('404') || e.message.match('401')) {
				setError('Недействительный токен')
			} else {
				const redirect = searchParams.get('redirect')
				if (redirect) {
					navigate(redirect)
				} else {
					navigate('/')
				}
			}
		} finally {
			setIsLoading(false);
		}

	}

	const inputChange = (e) => {
		setToken(e.target.value)
		setError(null)
	}

	return (
		<div>
			<section className="main-section">
				<div className="block">
					<div className="main-title">Авторизация</div>
					<div className="descr">На данный момент мы можем вас авторизовать только через API токен.</div>
					<div className="buttons">
						<button className="button-big white" onClick={() => setShowAuth(true)}>Хорошо</button>
					</div>
				</div>
			</section>

			{showAuth ? <div className="ovg-modal-backdrop show"></div>: ''}
			{showAuth ? 
	      <div className="ovg-modal-window show" onClick={(e) => {!isLoading && setShowAuth(!(e.target.className.match('ovg-modal-window show') || e.target.className.match('hide')))}}>
			    <div className="modal-block modal-block_medium" style={{'width': '440px'}}>
	          <div className="modal-block__title">
	            <span> Авторизация </span>
	          </div>

	          <div className="modal-block__content" style={{'padding': '0 24px'}}>
	            <div className="row">
	              <div className="col-36">
	                <label> Мы храним токен на вашем устройстве, не показывайте его третьему лицу! </label>
	                <br></br>
									<br></br>
	                <label> Где найти токен? <a href="https://wasd.tv/general-settings/API" target="_blank" rel="noreferrer"> Токен API </a> </label>
	              </div>
	              <div className="col-64">
	                <wasd-input>
	                  <div ovg="" className="wasd-input-wrapper" style={{flexDirection: 'column', alignItems: 'stretch'}}>
	                    <div ovg="" className="wasd-input">
	                      <input ovg="" placeholder="Ваш токен" type="text" className={classnames('api-token', isLoading ? 'disabled' : '')} onChange={inputChange}></input>
	                    </div>
											{error ? <span className="error" style={{marginTop: '5px'}}>{error}</span> : ''}
	                  </div>
	                 </wasd-input>
	              </div>
	              <div className="col-36">
									<br></br>
	                <label style={{fontSize: '13px'}}> *Сгененируцте новый токен а после чего вставьте в поле выше* </label>
									<br></br>
									<br></br>
	              </div>
	            </div>
	          </div>

	          <div className="modal-block__footer">
	            <div className="flat-btn ovg" style={{'display': 'flex'}}>
	              <button className={classnames('medium', 'ovg', 'basic', 'hide', isLoading ? 'disabled' : '')} style={{'marginRight': '5px'}}> отмена </button>
	              <button className={classnames('primary', 'medium', 'ovg', 'updateUser', isLoading ? 'disabled' : '')} onClick={() => onSubmit() }> проверить </button>
	            </div>
	          </div>
	        </div>
	      </div>
			: '' }
		</div>
	);
};

export default Home;